import Foundation

public enum ParityStatus: String, Codable, CaseIterable, Sendable {
    case missing, partial, awaitingComparison, verified
    public var title: String {
        switch self { case .missing: return "Missing"; case .partial: return "Partial implementation"; case .awaitingComparison: return "Reference comparison required"; case .verified: return "Reference parity verified" }
    }
}

public struct ParityFeature: Codable, Identifiable, Sendable {
    public let id: String
    public let tool: StudioTool
    public let category: String
    public let name: String
    public let status: ParityStatus
    public let reference: String
    public let implementation: [String]
    public let acceptance: [String]
    public let limitation: String
    public let comparisonEvidence: [String]
}

public enum ParityLedger {
    public static let scope = "Desktop workflows. Photoshop 27.10 and After Effects 26.3 are the local reference baseline. Other product versions need confirmation."
    public static let warning = "This ledger is an audit baseline, not an exhaustive denominator. Unlisted features are not presumed supported. Local regression tests do not establish Adobe parity."
    public static let gates = [
        "Define the inputs, settings, shortcuts, and observable result against a named reference version.",
        "Represent the feature in the document model without losing editable data on save and reopen.",
        "Verify normal, boundary, cancellation, selection, and locked-layer behavior.",
        "Verify undo, redo, import, export, and interaction with related features.",
        "Compare reference fixtures, output pixels or samples, and file interoperability before marking parity verified."
    ]
    public static func reference(for tool: StudioTool) -> String {
        switch tool {
        case .pixel: return "https://helpx.adobe.com/ca/photoshop/desktop.html"
        case .form: return "https://helpx.adobe.com/illustrator/using/tools-in-illustrator.html"
        case .press: return "https://helpx.adobe.com/pdf/indesign_reference.pdf"
        case .lens: return "https://helpx.adobe.com/pdf/lightroom_reference.pdf"
        case .cut: return "https://helpx.adobe.com/in/premiere/desktop/edit-projects/intro-to-editing/edit-video-in-premiere.html"
        case .motion: return "https://helpx.adobe.com/pdf/after_effects_reference.pdf"
        case .sound: return "https://helpx.adobe.com/pdf/audition_reference.pdf"
        case .frame: return "https://helpx.adobe.com/ca/animate/using/authoring-panels.html"
        case .folio: return "https://helpx.adobe.com/pdf/acrobat_reference.pdf"
        case .code: return "https://helpx.adobe.com/ee/dreamweaver/user-guide.html"
        case .batch: return "https://helpx.adobe.com/media-encoder/user-guide.html"
        case .space: return "https://helpx.adobe.com/substance-3d-stager/get-started.html"
        }
    }
